INSERT INTO chats (id, position, name, initials, color, preview, time, unread, pinned, muted, is_group) VALUES ('fury', 8, 'Nick Fury', 'NF', 'gray', 'Nick Fury: Briefing at 0600 on the deck.', 'Wednesday', 0, 0, 0, 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('av1', 'avengers', 0, 'Steve Rogers', 'SR', 'blue', '8:40 AM', 'Sokovia relief convoy rolls out at dawn. I need two flyers on escort.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('av2', 'avengers', 1, 'Robert Downey Jr.', 'RDJ', 'red', '8:43 AM', 'Rhodey and I can take the first leg over the mountains.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('av3', 'avengers', 2, 'Sam Wilson', 'SW', 'teal', '8:47 AM', 'I''ll run the second leg and sweep the valley on the way back.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('av4', 'avengers', 3, 'Natasha Romanoff', 'NR', 'gray', '8:52 AM', 'Ground team is set. Clint has the supply manifest.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('av5', 'avengers', 4, 'Clint Barton', 'CB', 'purple', '8:58 AM', 'Manifest is clean. Sokovia gets forty pallets of medical gear.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('av6', 'avengers', 5, 'Thor', 'TH', 'gold', '9:02 AM', 'I will clear the pass ahead of the convoy. The roads are still buried.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('av7', 'avengers', 6, 'Bruce Banner', 'BB', 'green', '9:06 AM', 'I''ll watch the reactor readings from the compound. No surprises.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('av8', 'avengers', 7, 'Steve Rogers', 'SR', 'blue', '9:12 AM', 'Good. Full team brief at six. Relief convoy leaves at dawn.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('fu1', 'fury', 0, 'Nick Fury', 'NF', 'gray', '5:30 PM', 'Briefing moved to the Helicarrier. Do not be late.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('fu2', 'fury', 1, 'Robert Downey Jr.', 'RDJ', 'red', '5:32 PM', 'I''m never late. I arrive exactly when the show starts.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('fu3', 'fury', 2, 'Nick Fury', 'NF', 'gray', '5:34 PM', 'The Sokovia convoy needs Stark air support. Hill has the flight plan.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('fu4', 'fury', 3, 'Robert Downey Jr.', 'RDJ', 'red', '5:37 PM', 'Send it over. I''ll have the suit loaded by morning.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('fu5', 'fury', 4, 'Nick Fury', 'NF', 'gray', '5:40 PM', 'Maria will meet you on the deck at 0600.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('fu6', 'fury', 5, 'Nick Fury', 'NF', 'gray', '5:45 PM', 'Briefing at 0600 on the deck. Bring the suit.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('gu1', 'guardians', 0, 'Rocket', 'RK', 'orange', '2:10 PM', 'The jump drive is humming again. Mostly.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('gu2', 'guardians', 1, 'Robert Downey Jr.', 'RDJ', 'red', '2:14 PM', 'Define mostly. The last mostly cost me a quinjet.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('gu3', 'guardians', 2, 'Peter Quill', 'PQ', 'teal', '2:22 PM', 'We''re three jumps from Knowhere. Nobody touch the drive.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('gu4', 'guardians', 3, 'Gamora', 'GA', 'green', '2:25 PM', 'Quill, that is the third time you have said that this week.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('gu5', 'guardians', 4, 'Groot', 'GR', 'gray', '2:30 PM', 'I am Groot.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('gu6', 'guardians', 5, 'Rocket', 'RK', 'orange', '2:36 PM', 'He says the drive smells like burnt insulation. I say it''s fine.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('gu7', 'guardians', 6, 'Robert Downey Jr.', 'RDJ', 'red', '2:40 PM', 'Land at the tower. I''ll have a mechanic look before it strands you.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('gu8', 'guardians', 7, 'Peter Quill', 'PQ', 'teal', '2:44 PM', 'Deal. Also, that is my cassette in your lab.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pe1', 'pepper', 0, 'Pepper Potts', 'PP', 'green', '9:20 AM', 'Morning. The board moved the arc reactor review to Thursday.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pe2', 'pepper', 1, 'Robert Downey Jr.', 'RDJ', 'red', '9:22 AM', 'Good. I''ll have the Mark LXXXV telemetry ready by then.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pe3', 'pepper', 2, 'Pepper Potts', 'PP', 'green', '9:25 AM', 'They also want the Sokovia relief numbers in the deck.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pe4', 'pepper', 3, 'Robert Downey Jr.', 'RDJ', 'red', '9:28 AM', 'Maria has the convoy totals. I''ll pull them tonight.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pe5', 'pepper', 4, 'Pepper Potts', 'PP', 'green', '9:33 AM', 'Perfect. And please eat before the gala this time.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pe6', 'pepper', 5, 'Robert Downey Jr.', 'RDJ', 'red', '9:35 AM', 'One shawarma stop, then straight to the tower.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pe7', 'pepper', 6, 'Pepper Potts', 'PP', 'green', '9:41 AM', 'Board review is locked for Thursday. Don''t be late.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pp1', 'peter', 0, 'Peter Parker', 'PP', 'red', '9:48 AM', 'Mr. Stark, the web shooter firmware drops the link past forty miles an hour.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pp2', 'peter', 1, 'Robert Downey Jr.', 'RDJ', 'red', '9:50 AM', 'That is the driver, not the hardware. I pushed a new build to your rig.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pp3', 'peter', 2, 'Peter Parker', 'PP', 'red', '9:52 AM', 'Flashed it. The link holds at sixty, but the tracker pulls left in crosswind.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pp4', 'peter', 3, 'Robert Downey Jr.', 'RDJ', 'red', '9:55 AM', 'Calibrate the gyro from the field menu. Two taps, takes a second.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pp5', 'peter', 4, 'Peter Parker', 'PP', 'red', '9:58 AM', 'Done. Can I run the field test over the Hudson tonight? Quiet airspace.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pp6', 'peter', 5, 'Robert Downey Jr.', 'RDJ', 'red', '10:01 AM', 'Fine. Stay under the bridge and log every shot you take.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pp7', 'peter', 6, 'Peter Parker', 'PP', 'red', '10:03 AM', 'Deal. I''ll bring the field notes to the lab tomorrow morning.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('pp8', 'peter', 7, 'Robert Downey Jr.', 'RDJ', 'red', '10:04 AM', 'Firmware v4 is locked. I''ll bring the spare cartridges.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('rh1', 'rhodey', 0, 'James Rhodes', 'JR', 'blue', '1:05 PM', 'The War Machine armor requisition is on your desk.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('rh2', 'rhodey', 1, 'Robert Downey Jr.', 'RDJ', 'red', '1:08 PM', 'Signed. Take the upgraded repulsors, they fix the heat issue.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('rh3', 'rhodey', 2, 'James Rhodes', 'JR', 'blue', '1:12 PM', 'About time. The old ones cooked my shoulders on the last drop.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('rh4', 'rhodey', 3, 'Robert Downey Jr.', 'RDJ', 'red', '1:16 PM', 'I also moved the ammo feed so it stops jamming at altitude.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('rh5', 'rhodey', 4, 'James Rhodes', 'JR', 'blue', '1:20 PM', 'Good. I''ll run a drop test over the base tonight.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('rh6', 'rhodey', 5, 'James Rhodes', 'JR', 'blue', '1:26 PM', 'Drop test over the base tonight. Bring earplugs.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('st1', 'strange', 0, 'Stephen Strange', 'SS', 'orange', '11:02 AM', 'The Sanctum wards held through the night, if you were worried.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('st2', 'strange', 1, 'Robert Downey Jr.', 'RDJ', 'red', '11:06 AM', 'I wasn''t. The tower sensors spiked at three in the morning.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('st3', 'strange', 2, 'Stephen Strange', 'SS', 'orange', '11:10 AM', 'A dimensional hiccup. The mirror dimension does that when it rains.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('st4', 'strange', 3, 'Robert Downey Jr.', 'RDJ', 'red', '11:14 AM', 'Can you gate the Sokovia supplies instead of flying them?', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('st5', 'strange', 4, 'Stephen Strange', 'SS', 'orange', '11:20 AM', 'I can open a gate for the medical pallets at dawn.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('st6', 'strange', 5, 'Stephen Strange', 'SS', 'orange', '11:26 AM', 'Gate opens at dawn. Do not send anything alive through it.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wk1', 'wakanda', 0, 'Shuri', 'SH', 'purple', '8:20 AM', 'The maglev is waiting on the palace pad. Do not be late again.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wk2', 'wakanda', 1, 'Robert Downey Jr.', 'RDJ', 'red', '8:24 AM', 'That was one time, Shuri. The suit needed a patch.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wk3', 'wakanda', 2, 'Okoye', 'OK', 'gold', '8:28 AM', 'The Dora Milaje will escort the delegation from the landing pad.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wk4', 'wakanda', 3, 'T''Challa', 'TC', 'blue', '8:33 AM', 'The council wants the vibranium exchange proposal before lunch.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wk5', 'wakanda', 4, 'Robert Downey Jr.', 'RDJ', 'red', '8:38 AM', 'I''ll walk them through the reactor containment design myself.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wk6', 'wakanda', 5, 'Shuri', 'SH', 'purple', '8:48 AM', 'Better. I also fixed your palm repulsor calibration. It was embarrassing.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wk7', 'wakanda', 6, 'T''Challa', 'TC', 'blue', '8:55 AM', 'Wakanda welcomes you, Stark. Bring the shawarma this time.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wn1', 'wanda', 0, 'Wanda Maximoff', 'WM', 'purple', '4:02 PM', 'Training at the compound tomorrow at seven?', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wn2', 'wanda', 1, 'Robert Downey Jr.', 'RDJ', 'red', '4:05 PM', 'Make it eight. I''m upgrading the training room walls.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wn3', 'wanda', 2, 'Wanda Maximoff', 'WM', 'purple', '4:08 PM', 'Afraid I''ll break them again?', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wn4', 'wanda', 3, 'Robert Downey Jr.', 'RDJ', 'red', '4:10 PM', 'You did turn a reinforced wall into confetti.', 1);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wn5', 'wanda', 4, 'Wanda Maximoff', 'WM', 'purple', '4:14 PM', 'Vision says the new dampeners can take it. Eight it is.', 0);
INSERT INTO chat_messages (id, chat_id, position, author, initials, color, time, text, own) VALUES ('wn6', 'wanda', 5, 'Wanda Maximoff', 'WM', 'purple', '4:20 PM', 'I''ll bring the coffee. See you at eight.', 0);
